const inflight = new Map<string, Promise<Item>>();

export function load(key: string, fetchItem: (k: string) => Promise<Item>): Promise<Item> {
  const existing = inflight.get(key);
  if (existing) return existing;                     // join the flight
  const p = fetchItem(key).finally(() => inflight.delete(key));  // forget
  inflight.set(key, p);                              // inserted before any await
  return p;
}

