const byId = new DataLoader<string, Item>(async (keys) => {
  const rows = await db.itemsByIds([...keys]);      // one batched call
  const m = new Map(rows.map((r) => [r.id, r] as const));
  return keys.map((k) => m.get(k) ?? new Error(`missing ${k}`));  // per key, in order
